/**
 * The shuttle trajectory, solved rather than drawn.
 *
 * Generated by `node scripts/shuttle-trajectory.mjs`: an RK4 integration of
 * a = -g*j - (k/m)*|v|*v for a 5 g feathered shuttle with a 6.8 m/s
 * terminal velocity, launched at 151 km/h and 52 degrees.
 *
 * `apexFraction` is the number that matters. A parabola apexes at exactly
 * 0.500 of its range; drag pushes a shuttle's apex out to 0.683. That
 * asymmetry, a long climb and a near-vertical fall, is the visual signature of
 * the sport.
 *
 * SHUTTLE_FACTS is no longer rendered anywhere: the readings blocks were
 * removed from the page on 2026-10-11. It stays as the provenance record for
 * SHUTTLE_MOTION below, which is derived from this solution, so the numbers
 * that justify the easing are not left floating in a commit message.
 *
 * Regenerate rather than hand-editing.
 */

export const SHUTTLE_FACTS = {
  launchSpeedKmh: 151,
  launchDeg: 52,
  rangeM: 9.34,
  apexM: 6.15,
  hangTimeS: 2.22,
  terminalMs: 6.8,
  massG: 5,
  apexFraction: 0.683,
} as const;

/**
 * The hero entrance, taken from the same solution.
 *
 * `stagger` holds, for each element in order, the fraction of the flight at
 * which the shuttle had travelled that share of its arc. Drag front-loads the
 * flight, so these gaps widen: the first two elements arrive almost together
 * and the last two are far apart. The cascade decelerates the way the shuttle
 * does instead of ticking evenly.
 *
 * `ease` is a cubic-bezier fitted to normalised horizontal progress against
 * normalised time (RMS 0.00571 over 41 samples). It reaches a third of its
 * travel in the first tenth of the window, which is what v^2 drag looks like
 * expressed as a timing function.
 *
 * The window length itself is a UI decision, not a physical one: a literal
 * 2.22 s entrance would be unusable. Only the shape is derived.
 */
export const SHUTTLE_MOTION = {
  stagger: [0, 0.0714, 0.2731, 0.6989, 1],
  ease: "cubic-bezier(0, 0.242, 0.3, 0.883)",
} as const;
